-- LIB-22 · Chords over the lyrics (optional, per song)
--
-- chord_lyrics holds, per lyric section, the lyrics with ChordPro chords inline
-- ("[G]Amazing [C]grace"); chords_key is the key they're written in. Both are null for a
-- song without chords. The plain *_lyrics columns stay the source for search, first lines
-- and the derived columns, so the DB-02 triggers don't change.
--
-- Deploy safety: only adds nullable columns, so the build still live while this runs keeps
-- working (it never reads or writes them). Generated by drizzle-kit from db/schema/songs.ts.

ALTER TABLE "songs" ADD COLUMN "chord_lyrics" jsonb;--> statement-breakpoint
ALTER TABLE "songs" ADD COLUMN "chords_key" text;--> statement-breakpoint
ALTER TABLE "songs" ADD CONSTRAINT "songs_chords_key_check" CHECK ("songs"."chords_key" ~ '^[A-G](#|b)?m?$');--> statement-breakpoint
ALTER TABLE "songs" ADD CONSTRAINT "songs_chord_lyrics_check" CHECK (jsonb_typeof("songs"."chord_lyrics") = 'object');
